//! The cockpit models: `assets/models/cockpit_modern.glb` / `cockpit_classic.glb` (F-117A),
//! `cockpit_f16.glb` and `cockpit_uh60.glb`, exported from the Blender sources
//! `assets-src/blend/cockpit_*.blend` (`tools/models/export.sh`; the F-16's is generated by
//! `tools/models/build_cockpit_f16.py`, the UH-60A's by `build_cockpit_uh60.py`).
//!
//! Every visible part comes from the model. The game binds behaviour to it by material name
//! and by object custom properties (glTF extras):
//!
//! Materials:
//! * `panel_grey`, `dark`, `black`, `frame`, `seat`, `cushion`, `yellow`, `rubber`, `metal`,
//!   `highlight`: the shared cockpit materials (`CockpitMaterials`).
//! * `swatch`: the panel's solid parts, coloured by the live palette (UVs point at a cell of
//!   the 16x16 palette swatch: index = row * 16 + column).
//! * `atlas`: a lamp, readout, label or bezel button face drawn live into the instrument atlas.
//!   The object's `atlas_face` names the face (`layout`), `atlas_uv` the uv rectangle its UVs
//!   were made for; they are moved to wherever the face is in the atlas.
//! * `screen_left`, `screen_right`, `screen_third` (the F-117A's third MFD), `adi`, `approach`,
//!   `screen_rwr` (RWR scope), `hsi`, `ded` (data entry display): live displays (UVs 0..1 over
//!   the screen).
//! * `trackcam`, `trackcam_left`, `trackcam_third`: the tracking camera picture behind the
//!   right / left / third screen.
//! * `screen_scope`, `screen_board`, `screen_eo`, `screen_info`: an air defence console's air
//!   picture, track list, camera overlay and target data (`cockpit_console.glb`,
//!   `tools/models/build_console.py`; the camera picture is its `trackcam`). A console's buttons are `Console(Fire)` controls.
//! * `hud_glass`: the HUD combiner glass (the HUD is drawn collimated through it).
//! * `label_<TEXT>`: a side panel button label showing TEXT.
//! * Anything else is used as modelled (base colour, roughness, metallic).
//!
//! Object properties:
//! * `control` (effect, e.g. `Action(Gear)`, `HudMode(1)`, `Osb(Left, 3)`), `kind` (cap, osb,
//!   side, gear, eject), `half` ([x, y] half size of the face in metres), `height` (face above
//!   the object's origin, along +Z), `travel`: a pushable control; its face points along +Z.
//!   Its `moving` child is what moves when pressed; a `highlight` object under it is shown
//!   while a VR fingertip touches the control.
//! * `stick`, `throttle`: the levers (their origins: the stick pivot, the throttle handle at
//!   idle; the stick's `grip`: its grip centre above the pivot, metres); `anchor:
//!   "throttle_full"`: the handle at full thrust; `anchor: "throttle_pivot"`: a collective's
//!   pivot (the lever swings up about it instead of sliding).
//! * `lamp` ([r, g, b], linear) and `range`: a flood lamp (with the local lights option).
//! * `no_shadow`: casts no shadow.
//!
//! Every mesh but the HUD glass is `Solid` (the mouse points at it); the levers, the displays
//! and the atlas faces that are not buttons get their tooltips (`Tip`).
//!
//! The parts that never move or change material are drawn merged, one mesh per material (the
//! F-16's cockpit was 550 draws, 23 materials); their own meshes stay for the mouse, on a layer
//! no camera draws.

use std::collections::HashMap;

use bevy::camera::visibility::{NoFrustumCulling, RenderLayers};
use bevy::gltf::{Gltf, GltfMaterial, GltfMesh, GltfNode};
use bevy::light::NotShadowCaster;
use bevy::mesh::{Indices, PrimitiveTopology, VertexAttributeValues};
use bevy::prelude::*;

use super::controls::{Control, Highlight, Moving};
use super::displays::{self, CanvasRole, Face, LitMaterial, PanelMaterials, TrackCamScreen};
use super::hud_glass::HudGlassMaterial;
use super::layout::PanelLayout;
use super::levers::{CockpitAnchors, Stick, ThrottleLever};
use super::pick::Solid;
use super::shading::{CockpitMaterial, cockpit_material};
use super::tooltips;
use super::{CockpitLamp, CockpitMaterials};
use crate::font::Fonts;

/// The cockpit models of the flyable aircraft, by file stem.
#[derive(Resource)]
pub struct CockpitModels(pub std::collections::HashMap<&'static str, Handle<Gltf>>);

pub(super) fn load_models(mut commands: Commands, server: Res<AssetServer>) {
    let mut files = crate::aircraft::cockpit_files();
    files.push(super::CONSOLE_MODEL);
    commands.insert_resource(CockpitModels(
        files.into_iter().map(|f| (f, server.load(format!("models/{f}.glb")))).collect(),
    ));
}

impl CockpitMaterials {
    fn by_name(&self, name: &str) -> Option<&Handle<CockpitMaterial>> {
        Some(match name {
            "panel_grey" => &self.panel_grey,
            "dark" => &self.dark,
            "black" => &self.black,
            "frame" => &self.frame,
            "seat" => &self.seat,
            "cushion" => &self.cushion,
            "yellow" => &self.yellow,
            "rubber" => &self.rubber,
            "metal" => &self.metal,
            "highlight" => &self.highlight,
            _ => return None,
        })
    }
}

/// Assets read while spawning the model.
#[derive(bevy::ecs::system::SystemParam)]
pub(super) struct ModelAssets<'w> {
    pub gltfs: Res<'w, Assets<Gltf>>,
    pub nodes: Res<'w, Assets<GltfNode>>,
    pub meshes: Res<'w, Assets<GltfMesh>>,
    pub materials: Res<'w, Assets<GltfMaterial>>,
}

/// Where the spawned parts get their run-time materials and canvases.
pub(super) struct Spawner<'a> {
    pub mats: &'a CockpitMaterials,
    pub panel: &'a PanelMaterials,
    pub layout: &'a PanelLayout,
    pub fonts: &'a Fonts,
    pub tc_image: Option<&'a crate::trackcam::TrackCamImage>,
    pub classic_hud: bool,
    pub local_lights: bool,
    /// High-resolution MFD canvases.
    pub hires: bool,
    /// Modern HUD scale (`AircraftSpec::hud_scale`).
    pub hud_scale: f32,
    pub meshes: &'a mut Assets<Mesh>,
    pub materials: &'a mut Assets<CockpitMaterial>,
    pub hud_materials: &'a mut Assets<HudGlassMaterial>,
    pub images: &'a mut Assets<Image>,
    /// Modelled materials by glTF material (made once).
    modelled: HashMap<AssetId<GltfMaterial>, Handle<CockpitMaterial>>,
    /// The model has no tracking camera picture behind the left screen: one is made from the
    /// screen's mesh.
    left_trackcam_missing: bool,
    pub anchors: CockpitAnchors,
    /// The atlas faces by key (`atlas_face`).
    faces: HashMap<String, Face>,
    /// The parts drawn merged.
    still: Vec<StillPart>,
}

/// A part that never moves or changes material.
#[derive(Clone)]
struct StillPart {
    entity: Entity,
    mesh: Handle<Mesh>,
    material: Handle<CockpitMaterial>,
    /// Its place under the cockpit root.
    at: Transform,
    no_shadow: bool,
}

impl<'a> Spawner<'a> {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        mats: &'a CockpitMaterials,
        panel: &'a PanelMaterials,
        layout: &'a PanelLayout,
        fonts: &'a Fonts,
        tc_image: Option<&'a crate::trackcam::TrackCamImage>,
        classic_hud: bool,
        local_lights: bool,
        hires: bool,
        hud_scale: f32,
        meshes: &'a mut Assets<Mesh>,
        materials: &'a mut Assets<CockpitMaterial>,
        hud_materials: &'a mut Assets<HudGlassMaterial>,
        images: &'a mut Assets<Image>,
    ) -> Self {
        Self {
            mats,
            panel,
            layout,
            fonts,
            tc_image,
            classic_hud,
            local_lights,
            hires,
            hud_scale,
            meshes,
            materials,
            hud_materials,
            images,
            modelled: HashMap::new(),
            left_trackcam_missing: false,
            anchors: CockpitAnchors::default(),
            faces: displays::atlas_faces(layout)
                .into_iter()
                .map(|(f, _)| (format!("{f:?}"), f))
                .collect(),
            still: Vec::new(),
        }
    }

    /// Spawns the model's root objects under `root`. Returns false if the file is not loaded.
    pub fn spawn(
        &mut self,
        commands: &mut Commands,
        assets: &ModelAssets,
        file: &Handle<Gltf>,
        root: Entity,
    ) -> bool {
        let Some(g) = assets.gltfs.get(file) else { return false };
        let names: HashMap<AssetId<GltfMaterial>, String> =
            g.named_materials.iter().map(|(n, h)| (h.id(), n.to_string())).collect();
        self.left_trackcam_missing = !names.values().any(|n| n == "trackcam_left");
        let children: std::collections::HashSet<AssetId<GltfNode>> = g
            .nodes
            .iter()
            .filter_map(|n| assets.nodes.get(n))
            .flat_map(|n| n.children.iter().map(|c| c.id()))
            .collect();
        for n in g.nodes.iter().filter(|n| !children.contains(&n.id())) {
            let e = self.node(commands, assets, &names, n, Transform::IDENTITY, false);
            commands.entity(root).add_child(e);
        }
        self.merge_still(commands, root);
        true
    }

    /// The parts that never move or change material, merged into one mesh per material (and
    /// shadow casting) under `root`; theirs are left to the mouse.
    fn merge_still(&mut self, commands: &mut Commands, root: Entity) {
        let mut groups: HashMap<_, Vec<usize>> = HashMap::new();
        for (i, p) in self.still.iter().enumerate() {
            let Some(m) = self.meshes.get(&p.mesh) else { continue };
            let Some(kind) = mergeable(m) else { continue };
            groups.entry((p.material.id(), p.no_shadow, kind)).or_default().push(i);
        }
        for parts in groups.into_values().filter(|p| p.len() > 1) {
            let first = self.still[parts[0]].clone();
            let mut merged = Merged::default();
            for &i in &parts {
                let p = &self.still[i];
                if let Some(m) = self.meshes.get(&p.mesh) {
                    merged.add(m, &p.at);
                }
            }
            let e = commands
                .spawn((
                    Mesh3d(self.meshes.add(merged.mesh())),
                    MeshMaterial3d(first.material),
                    Transform::IDENTITY,
                    Visibility::default(),
                    NoFrustumCulling,
                ))
                .id();
            if first.no_shadow {
                commands.entity(e).insert(NotShadowCaster);
            }
            commands.entity(root).add_child(e);
            for &i in &parts {
                let undrawn = RenderLayers::layer(crate::camera::UNDRAWN_LAYER);
                commands.entity(self.still[i].entity).insert(undrawn);
            }
        }
    }

    fn node(
        &mut self,
        commands: &mut Commands,
        assets: &ModelAssets,
        names: &HashMap<AssetId<GltfMaterial>, String>,
        handle: &Handle<GltfNode>,
        parent: Transform,
        moves: bool,
    ) -> Entity {
        let Some(node) = assets.nodes.get(handle) else { return commands.spawn_empty().id() };
        let extras: serde_json::Value = node
            .extras
            .as_ref()
            .and_then(|x| serde_json::from_str(&x.value).ok())
            .unwrap_or_default();
        let at = parent * node.transform;
        let e = commands
            .spawn((Name::new(node.name.clone()), node.transform, Visibility::default()))
            .id();
        let mut ec = commands.entity(e);
        if extras.get("control").is_some() {
            match Control::from_model(&extras) {
                Some(c) => {
                    if c.is_eject() {
                        self.anchors.eject = at.translation;
                    }
                    ec.insert(c);
                }
                None => warn!("cockpit model: bad control {} on {}", extras["control"], node.name),
            }
        }
        if extras["moving"].as_bool() == Some(true) {
            ec.insert(Moving);
        }
        if extras["highlight"].as_bool() == Some(true) {
            ec.insert((Highlight, Visibility::Hidden));
        }
        if extras["stick"].as_bool() == Some(true) {
            ec.insert((Stick, tooltips::stick_tip()));
            self.anchors.stick_pivot = at.translation;
            if let Some(g) = extras["grip"].as_f64() {
                self.anchors.grip_height = g as f32;
            }
        }
        if extras["throttle"].as_bool() == Some(true) {
            ec.insert((ThrottleLever, tooltips::throttle_tip()));
            self.anchors.throttle_idle = at.translation;
        }
        if extras["anchor"].as_str() == Some("throttle_full") {
            self.anchors.throttle_full = at.translation;
        }
        if extras["anchor"].as_str() == Some("throttle_pivot") {
            self.anchors.throttle_pivot = Some(at.translation);
        }
        if let Some(c) = extras["lamp"].as_array()
            && self.local_lights
        {
            let f = |i: usize| c.get(i).and_then(|v| v.as_f64()).unwrap_or(1.0) as f32;
            ec.insert((
                CockpitLamp,
                PointLight {
                    intensity: 0.0,
                    range: extras["range"].as_f64().unwrap_or(1.6) as f32,
                    color: Color::linear_rgb(f(0), f(1), f(2)),
                    shadow_maps_enabled: false,
                    ..default()
                },
            ));
        }
        let no_shadow = extras["no_shadow"].as_bool() == Some(true);
        // What moves, lights up or is shown and hidden, with all under it.
        let moves = moves
            || ["control", "moving", "highlight", "stick", "throttle"]
                .iter()
                .any(|k| extras.get(k).is_some_and(|v| !v.is_null()));

        if let Some(mesh) = node.mesh.as_ref().and_then(|m| assets.meshes.get(m)) {
            let single = mesh.primitives.len() == 1;
            for prim in &mesh.primitives {
                let target = if single {
                    e
                } else {
                    commands.spawn((Transform::default(), Visibility::default())).id()
                };
                if !single {
                    commands.entity(e).add_child(target);
                }
                let name = prim
                    .material
                    .as_ref()
                    .and_then(|m| names.get(&m.id()))
                    .map_or("", String::as_str);
                let still = self.primitive(commands, target, name, prim, &extras, assets);
                if let Some((mesh, material)) = still.filter(|_| !moves) {
                    let entity = target;
                    self.still.push(StillPart { entity, mesh, material, at, no_shadow });
                }
                let mut t = commands.entity(target);
                t.insert(NoFrustumCulling);
                if name != "hud_glass" {
                    t.insert(Solid);
                }
                if no_shadow {
                    t.insert(NotShadowCaster);
                }
            }
        }
        let kids: Vec<Entity> = node
            .children
            .iter()
            .map(|c| self.node(commands, assets, names, c, at, moves))
            .collect();
        commands.entity(e).add_children(&kids);
        e
    }

    /// A mesh primitive with its run-time material (by material name). Its mesh and material
    /// if neither changes while flying.
    fn primitive(
        &mut self,
        commands: &mut Commands,
        e: Entity,
        name: &str,
        prim: &bevy::gltf::GltfPrimitive,
        extras: &serde_json::Value,
        assets: &ModelAssets,
    ) -> Option<(Handle<Mesh>, Handle<CockpitMaterial>)> {
        let mut mesh = prim.mesh.clone();
        let mut ec = commands.entity(e);
        let mut still = true;
        let material = match name {
            "swatch" => self.panel.solid.clone(),
            "atlas" => {
                if let Some(m) = self.atlas_mesh(&prim.mesh, extras) {
                    mesh = m;
                }
                let face = extras["atlas_face"].as_str().and_then(|k| self.faces.get(k));
                if let Some(tip) = face.and_then(|&f| tooltips::face_tip(f)) {
                    ec.insert(tip);
                }
                self.panel.atlas.clone()
            }
            "screen_scope" | "screen_board" | "screen_eo" | "screen_info" => {
                let screen = match name {
                    "screen_scope" => displays::ConsoleScreen::Scope,
                    "screen_board" => displays::ConsoleScreen::Board,
                    "screen_info" => displays::ConsoleScreen::Info,
                    _ => displays::ConsoleScreen::Eo,
                };
                let role = CanvasRole::Console(screen);
                let (tex, m) =
                    displays::screen(role, self.layout, self.hires, self.materials, self.images);
                ec.insert((role, displays::ConsoleCanvas(screen), tex));
                if let Some(tip) = tooltips::display_tip(role, self.layout.style) {
                    ec.insert(tip);
                }
                still = false;
                m
            }
            "screen_left" | "screen_right" | "screen_third" | "adi" | "approach" | "screen_rwr"
            | "hsi" | "ded" => {
                let role = match name {
                    "screen_left" => CanvasRole::Left,
                    "screen_right" => CanvasRole::Right,
                    "screen_third" => CanvasRole::Third,
                    "adi" => CanvasRole::Adi,
                    "screen_rwr" => CanvasRole::Rwr,
                    "hsi" => CanvasRole::Hsi,
                    "ded" => CanvasRole::Ded,
                    _ => CanvasRole::Approach,
                };
                let (tex, m) =
                    displays::screen(role, self.layout, self.hires, self.materials, self.images);
                ec.insert((role, tex));
                if let Some(tip) = tooltips::display_tip(role, self.layout.style) {
                    ec.insert(tip);
                }
                if role == CanvasRole::Left && self.left_trackcam_missing {
                    self.left_trackcam(commands, e, &prim.mesh);
                }
                still = false;
                m
            }
            "trackcam" | "trackcam_left" | "trackcam_third" => {
                let side = match name {
                    "trackcam" => crate::mfd::MfdSide::Right,
                    "trackcam_left" => crate::mfd::MfdSide::Left,
                    _ => crate::mfd::MfdSide::Third,
                };
                ec.insert((TrackCamScreen(side), Visibility::Hidden));
                still = false;
                displays::trackcam_material(self.materials, self.tc_image)
            }
            "hud_glass" => {
                let (tex, m) = displays::hud_material(
                    self.hud_materials,
                    self.images,
                    self.classic_hud,
                    self.hud_scale,
                );
                ec.insert((
                    CanvasRole::Hud,
                    super::HudGlass,
                    tex,
                    Mesh3d(mesh),
                    MeshMaterial3d(m),
                    NotShadowCaster,
                ));
                return None;
            }
            n if n.starts_with("label_") => {
                let text = &n["label_".len()..];
                let (tex, m) = displays::side_label(text, self.fonts, self.materials, self.images);
                let label = displays::SideLabel { text: text.to_string(), lit: None };
                ec.insert((tex, label, LitMaterial(m.clone())));
                still = false;
                m
            }
            n => match self.mats.by_name(n) {
                Some(m) => m.clone(),
                None => self.modelled(prim.material.as_ref(), assets),
            },
        };
        commands.entity(e).insert((Mesh3d(mesh.clone()), MeshMaterial3d(material.clone())));
        still.then_some((mesh, material))
    }

    /// The tracking camera picture 3 mm behind the left screen, from the screen's mesh.
    fn left_trackcam(&mut self, commands: &mut Commands, screen: Entity, mesh: &Handle<Mesh>) {
        let Some(m) = self.meshes.get(mesh) else { return };
        let Some(VertexAttributeValues::Float32x3(p)) = m.attribute(Mesh::ATTRIBUTE_POSITION)
        else {
            return;
        };
        if p.len() < 3 {
            return;
        }
        let v: Vec<Vec3> = p.iter().map(|&a| Vec3::from(a)).collect();
        let centre = v.iter().copied().sum::<Vec3>() / v.len() as f32;
        // Normal towards the eye (the cockpit frame's origin).
        let mut n = (v[1] - v[0]).cross(v[2] - v[0]).normalize_or_zero();
        if n.dot(-centre) < 0.0 {
            n = -n;
        }
        let material = displays::trackcam_material(self.materials, self.tc_image);
        let child = commands
            .spawn((
                Mesh3d(mesh.clone()),
                MeshMaterial3d(material),
                Transform::from_translation(-n * 0.003),
                TrackCamScreen(crate::mfd::MfdSide::Left),
                Visibility::Hidden,
                NoFrustumCulling,
                NotShadowCaster,
            ))
            .id();
        commands.entity(screen).add_child(child);
    }

    /// The face's mesh with its UVs moved to the face's place in the instrument atlas.
    fn atlas_mesh(
        &mut self,
        mesh: &Handle<Mesh>,
        extras: &serde_json::Value,
    ) -> Option<Handle<Mesh>> {
        let key = extras["atlas_face"].as_str()?;
        let Some(&(n0, n1)) = self.panel.faces.get(key) else {
            warn!("cockpit model: no atlas face {key}");
            return None;
        };
        let r: Vec<f32> = extras["atlas_uv"]
            .as_array()?
            .iter()
            .filter_map(|v| v.as_f64().map(|x| x as f32))
            .collect();
        let (o0, o1) = (Vec2::new(*r.first()?, *r.get(1)?), Vec2::new(*r.get(2)?, *r.get(3)?));
        let mut m = self.meshes.get(mesh)?.clone();
        if let Some(VertexAttributeValues::Float32x2(uv)) = m.attribute_mut(Mesh::ATTRIBUTE_UV_0) {
            for u in uv.iter_mut() {
                let t = (Vec2::from(*u) - o0) / (o1 - o0).max(Vec2::splat(1e-6));
                *u = (n0 + t * (n1 - n0)).to_array();
            }
        }
        Some(self.meshes.add(m))
    }

    /// A material as modelled in Blender.
    fn modelled(
        &mut self,
        material: Option<&Handle<GltfMaterial>>,
        assets: &ModelAssets,
    ) -> Handle<CockpitMaterial> {
        let Some(h) = material else { return self.mats.panel_grey.clone() };
        if let Some(m) = self.modelled.get(&h.id()) {
            return m.clone();
        }
        let m =
            assets.materials.get(h).map_or_else(StandardMaterial::default, |g| StandardMaterial {
                base_color: g.base_color,
                base_color_texture: g.base_color_texture.clone(),
                emissive: g.emissive,
                perceptual_roughness: g.perceptual_roughness,
                metallic: g.metallic,
                fog_enabled: false,
                ..default()
            });
        let m = self.materials.add(cockpit_material(m));
        self.modelled.insert(h.id(), m.clone());
        m
    }
}

/// Which attributes a mesh that can be merged has (normals, UVs, tangents), or None.
fn mergeable(m: &Mesh) -> Option<(bool, bool, bool)> {
    if m.primitive_topology() != PrimitiveTopology::TriangleList {
        return None;
    }
    let known = [
        Mesh::ATTRIBUTE_POSITION.id,
        Mesh::ATTRIBUTE_NORMAL.id,
        Mesh::ATTRIBUTE_UV_0.id,
        Mesh::ATTRIBUTE_TANGENT.id,
    ];
    if m.attributes().any(|(a, _)| !known.contains(&a.id)) {
        return None;
    }
    let has = |a| m.attribute(a).is_some();
    has(Mesh::ATTRIBUTE_POSITION).then_some((
        has(Mesh::ATTRIBUTE_NORMAL),
        has(Mesh::ATTRIBUTE_UV_0),
        has(Mesh::ATTRIBUTE_TANGENT),
    ))
}

/// Meshes of the same attributes (`mergeable`) put together in their parent's frame.
#[derive(Default)]
struct Merged {
    positions: Vec<[f32; 3]>,
    normals: Vec<[f32; 3]>,
    uvs: Vec<[f32; 2]>,
    tangents: Vec<[f32; 4]>,
    indices: Vec<u32>,
}

impl Merged {
    fn add(&mut self, m: &Mesh, at: &Transform) {
        let Some(VertexAttributeValues::Float32x3(p)) = m.attribute(Mesh::ATTRIBUTE_POSITION)
        else {
            return;
        };
        let base = self.positions.len() as u32;
        let affine = at.compute_affine();
        let normal = affine.matrix3.inverse().transpose();
        self.positions.extend(p.iter().map(|&v| affine.transform_point3(v.into()).to_array()));
        if let Some(VertexAttributeValues::Float32x3(n)) = m.attribute(Mesh::ATTRIBUTE_NORMAL) {
            let n = n.iter().map(|&v| (normal * Vec3::from(v)).normalize_or_zero().to_array());
            self.normals.extend(n);
        }
        if let Some(VertexAttributeValues::Float32x2(uv)) = m.attribute(Mesh::ATTRIBUTE_UV_0) {
            self.uvs.extend(uv);
        }
        if let Some(VertexAttributeValues::Float32x4(t)) = m.attribute(Mesh::ATTRIBUTE_TANGENT) {
            self.tangents.extend(t.iter().map(|&[x, y, z, w]| {
                let d = affine.matrix3 * Vec3::new(x, y, z);
                let w = if affine.matrix3.determinant() < 0.0 { -w } else { w };
                d.normalize_or_zero().extend(w).to_array()
            }));
        }
        // (A mirrored part's winding is left: the glTF loader turned it for its mirroring.)
        match m.indices() {
            Some(Indices::U16(i)) => self.indices.extend(i.iter().map(|&i| base + i as u32)),
            Some(Indices::U32(i)) => self.indices.extend(i.iter().map(|&i| base + i)),
            None => self.indices.extend(base..base + p.len() as u32),
        }
    }

    fn mesh(self) -> Mesh {
        let mut m = Mesh::new(PrimitiveTopology::TriangleList, Default::default())
            .with_inserted_attribute(Mesh::ATTRIBUTE_POSITION, self.positions)
            .with_inserted_indices(Indices::U32(self.indices));
        if !self.normals.is_empty() {
            m.insert_attribute(Mesh::ATTRIBUTE_NORMAL, self.normals);
        }
        if !self.uvs.is_empty() {
            m.insert_attribute(Mesh::ATTRIBUTE_UV_0, self.uvs);
        }
        if !self.tangents.is_empty() {
            m.insert_attribute(Mesh::ATTRIBUTE_TANGENT, self.tangents);
        }
        m
    }
}

#[cfg(test)]
mod tests {
    use super::super::controls::parse_effect;
    use super::super::displays::atlas_faces;
    use super::super::layout::{PanelLayout, PanelStyle};

    /// The JSON part of a .glb file.
    fn gltf_json(name: &str) -> serde_json::Value {
        let path = format!("{}/assets/models/{name}.glb", env!("CARGO_MANIFEST_DIR"));
        let d = std::fs::read(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
        let len = u32::from_le_bytes(d[12..16].try_into().unwrap()) as usize;
        serde_json::from_slice(&d[20..20 + len]).unwrap()
    }

    /// The air defence console has its screens, the camera picture, and buttons for every
    /// console key the station reads.
    #[test]
    fn console_model() {
        use super::super::controls::parse_effect;
        use super::super::layout::{ConsoleKey, Effect};
        let j = gltf_json(super::super::CONSOLE_MODEL);
        let materials: Vec<&str> =
            j["materials"].as_array().unwrap().iter().filter_map(|m| m["name"].as_str()).collect();
        for m in
            ["screen_scope", "screen_board", "screen_eo", "screen_info", "trackcam", "label_FIRE"]
        {
            assert!(materials.contains(&m), "no material {m}");
        }
        let keys: Vec<ConsoleKey> = j["nodes"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|n| n["extras"]["control"].as_str())
            .map(|c| match parse_effect(c) {
                Some(Effect::Console(k)) => k,
                e => panic!("{c}: {e:?}"),
            })
            .collect();
        for k in [
            ConsoleKey::Tracks,
            ConsoleKey::Site,
            ConsoleKey::Lock,
            ConsoleKey::Drop,
            ConsoleKey::Guided,
            ConsoleKey::Semi,
            ConsoleKey::Fire,
            ConsoleKey::Launcher(3),
            ConsoleKey::Refill(3),
            ConsoleKey::Flir,
            ConsoleKey::ZoomIn,
            ConsoleKey::ZoomOut,
            ConsoleKey::RangeIn,
            ConsoleKey::RangeOut,
            ConsoleKey::Leave,
        ] {
            assert!(keys.contains(&k), "no {k:?} button");
        }
    }

    /// A generated panel's layout as its Blender build script reads it: every atlas face with
    /// its rectangle (millimetres, x right / y down from the panel centre) and, for buttons,
    /// the control it fires; the display rectangles (the F-117A's third MFD as `third`, the
    /// F-16's HSI and RWR scope as `hsi` and `rwr`).
    fn layout_json(style: PanelStyle) -> serde_json::Value {
        use super::super::displays::Face;
        use super::super::layout::Effect;
        let l = PanelLayout::for_style(style);
        let r = |r: &super::super::layout::PxRect| serde_json::json!([r.x, r.y, r.w, r.h]);
        let faces: Vec<serde_json::Value> = atlas_faces(&l)
            .iter()
            .enumerate()
            .map(|(i, (face, rect))| {
                let (control, kind) = match face {
                    Face::Osb(side, slot) => (Some(Effect::Osb(*side, *slot)), Some("osb")),
                    _ => (l.items.get(i).and_then(|p| p.cap), Some("cap")),
                };
                let kind = control.and(kind);
                let round = l.items.get(i).is_some_and(|p| p.round);
                serde_json::json!({"key": format!("{face:?}"), "rect": r(rect), "control": control.map(|c| format!("{c:?}")), "kind": kind, "round": round})
            })
            .collect();
        let mut screens = serde_json::json!({"adi": r(&l.adi), "ded": r(&l.ded.unwrap())});
        for (m, key) in l.mfds.iter().zip(["left", "right", "third"]) {
            screens[key] = r(&m.screen);
        }
        for (rect, key) in [(l.hsi, "hsi"), (l.rwr, "rwr")] {
            if let Some(rect) = rect {
                screens[key] = r(&rect);
            }
        }
        serde_json::json!({"faces": faces, "screens": screens})
    }

    /// `assets-src/blend/cockpit_f16_layout.json` and `cockpit_modern_layout.json` match the
    /// layouts (rewritten with `UPDATE_LAYOUT=1 cargo test layout_files`, then rebuild the
    /// models).
    #[test]
    fn layout_files() {
        for (style, name, script) in [
            (PanelStyle::F16, "cockpit_f16", "build_cockpit_f16"),
            (PanelStyle::Modern, "cockpit_modern", "build_cockpit_f117"),
            (PanelStyle::Uh60, "cockpit_uh60", "build_cockpit_uh60"),
            (PanelStyle::Ah1z, "cockpit_ah1z", "build_cockpit_ah1z"),
        ] {
            let path =
                format!("{}/assets-src/blend/{name}_layout.json", env!("CARGO_MANIFEST_DIR"));
            let want = serde_json::to_string_pretty(&layout_json(style)).unwrap() + "\n";
            if std::env::var_os("UPDATE_LAYOUT").is_some() {
                std::fs::write(&path, &want).unwrap();
            }
            let have = std::fs::read_to_string(&path).unwrap_or_default();
            assert!(
                have == want,
                "{path} is stale: run UPDATE_LAYOUT=1 cargo test layout_files and tools/models/{script}.py"
            );
        }
    }

    /// Every cockpit model has everything the game binds to, and nothing it can't read.
    #[test]
    fn cockpit_models() {
        for (name, style) in [
            ("cockpit_modern", PanelStyle::Modern),
            ("cockpit_classic", PanelStyle::Classic),
            ("cockpit_f16", PanelStyle::F16),
            ("cockpit_uh60", PanelStyle::Uh60),
            ("cockpit_ah1z", PanelStyle::Ah1z),
        ] {
            let j = gltf_json(name);
            let nodes = j["nodes"].as_array().unwrap();
            let extras: Vec<&serde_json::Value> = nodes.iter().map(|n| &n["extras"]).collect();
            let materials: Vec<&str> = j["materials"]
                .as_array()
                .unwrap()
                .iter()
                .filter_map(|m| m["name"].as_str())
                .collect();
            let mut required = vec![
                "atlas",
                "screen_left",
                "screen_right",
                "adi",
                "approach",
                "trackcam",
                "hud_glass",
            ];
            // The generated cockpits' MENU buttons are caps of their up-front controls (atlas
            // faces).
            required.extend(match style {
                PanelStyle::F16 => vec!["screen_rwr", "hsi", "ded", "trackcam_left", "label_NEAR"],
                PanelStyle::Modern => {
                    vec!["screen_third", "ded", "trackcam_left", "trackcam_third", "label_NEAR"]
                }
                PanelStyle::Uh60 | PanelStyle::Ah1z => vec!["ded", "trackcam_left", "label_NEAR"],
                PanelStyle::Classic => vec!["swatch", "label_MENU"],
            });
            for m in required {
                assert!(materials.contains(&m), "{name}: no material {m}");
            }
            let has = |k: &str| extras.iter().filter(|x| x.get(k).is_some()).count();
            assert_eq!(has("stick"), 1, "{name}: stick");
            assert_eq!(has("throttle"), 1, "{name}: throttle");
            assert!(
                extras.iter().any(|x| x["anchor"] == "throttle_full"),
                "{name}: throttle_full anchor"
            );
            // The throttle travels the whole rail (a collective its arc): idle (its origin) to
            // full well apart.
            let pos = |k: &str, v: serde_json::Value| {
                let n = nodes
                    .iter()
                    .find(|n| n["extras"][k] == v)
                    .unwrap_or_else(|| panic!("{name}: no {k} node"));
                let c = |i: usize| n["translation"][i].as_f64().unwrap_or(0.0);
                bevy::math::DVec3::new(c(0), c(1), c(2))
            };
            let travel =
                pos("throttle", true.into()).distance(pos("anchor", "throttle_full".into()));
            assert!(travel > 0.15, "{name}: throttle travel {travel} m");
            assert!(extras.iter().any(|x| x["kind"] == "eject"), "{name}: ejection handle");
            assert!(extras.iter().any(|x| x["control"] == "Action(Menu)"), "{name}: MENU button");
            assert!(
                extras.iter().any(|x| x["control"] == "Action(MasterCaution)"),
                "{name}: master caution button"
            );
            let keys: Vec<String> = atlas_faces(&PanelLayout::for_style(style))
                .iter()
                .map(|(f, _)| format!("{f:?}"))
                .collect();
            for x in &extras {
                if let Some(c) = x["control"].as_str() {
                    assert!(parse_effect(c).is_some(), "{name}: control {c}");
                    assert!(
                        super::super::controls::Control::from_model(x).is_some(),
                        "{name}: control {x}"
                    );
                }
                if let Some(f) = x["atlas_face"].as_str() {
                    assert!(
                        keys.iter().any(|k| k == f),
                        "{name}: atlas face {f} not in the layout"
                    );
                }
            }
            if style != PanelStyle::Classic {
                // The generated models have every face of their layouts.
                for k in &keys {
                    assert!(
                        extras.iter().any(|x| x["atlas_face"].as_str() == Some(k)),
                        "{name}: no atlas face {k}"
                    );
                }
            }
        }
    }
}
